  "rule": ScopeRule.describe("Which branch decided"),
  "reason": z.string().describe("Plain-language reason"),
  "term": z.string().nullable().optional().describe("The strong term that matched"),
  "topics": z.array(z.string()).describe("Top-level topic ids that matched"),
